import{z as A,x as B,o as n,c as h,q as t,j as i,D as E,d as e,s as o,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"IFEval / IFBench","description":"","frontmatter":{"title":"IFEval / IFBench","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ifbench.md","filePath":"llm/ifbench.md","lastUpdated":1791413859000}'),c={name:"llm/ifbench.md"};function p(d,a,m,F,I,v){const r=B("Mermaid");return n(),h("div",null,[a[2]||(a[2]=t('<h1 id="ifeval-ifbench" tabindex="-1">IFEval / IFBench <a class="header-anchor" href="#ifeval-ifbench" aria-label="Permalink to &quot;IFEval / IFBench&quot;">​</a></h1><div class="epigraph"><p>可验证约束把指令遵循收成程序谓词；一旦模型把那二十五个检查函数背熟，同一套谓词上的高分就不再说明遇到新约束仍会服从。需要一张约束类型被留出的卷子。</p><footer>—— Zhou et al., IFEval；Pyatkin 等 IFBench 将新约束当作分布外服从测试</footer></div><p><a href="/llm/niah-variants">上一课</a>把标准单针 NIAH 写成检索冒烟，并用多针、干扰、运算与草堆改命题。那是长上下文检索，不是格式服从。<a href="/llm/ifeval">IFEval</a> 已经把「听不听指令」拆成可验证谓词，prompt-level 与 instruction-level 成为回归门禁。缺口是这张函数表会过拟合：强化学习若直接拿 verifier 当奖励，分数涨可能只是会做见过的格式体操。IFBench 用留出约束类型测服从有没有泛化，检查器族与 IFEval 刻意错开。本课把二者当成同一条尺子的校准端与留出端，不重写 NIAH 变体网格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>助手失败里有一类极具体：内容对，格式错。用户要三段、禁某个词、输出 JSON，模型漏一条。主观偏好评测会原谅它，下游解析器不会。IFEval 证明这件事可以自动考。可一旦它成为公开门禁，训练就会看见同一批谓词：长度上下限怎么凑、标题 markdown 怎么写、禁用词怎么用同形字绕过。分数涨，可能是学会了服从，也可能是学会了这二十五个函数。</p><p>指令遵循的泛化问题与 <a href="/llm/eval-contamination">MMLU 污染</a> 同类，但更窄：泄漏的不是题面，是<strong>约束生成器</strong>。留出新的原子约束、新的组合模板、新的表层实现（例如另一种列表语法、另一种计数单位），才能区分「服从通道」和「背检查器」。IFBench 的存在理由就是这张留出卷，而不是把 IFEval 再出一遍更长的题。</p><h3 id="可验证通过仍可能无用-留出失败则说明服从没泛化" tabindex="-1">可验证通过仍可能无用，留出失败则说明服从没泛化 <a class="header-anchor" href="#可验证通过仍可能无用-留出失败则说明服从没泛化" aria-label="Permalink to &quot;可验证通过仍可能无用，留出失败则说明服从没泛化&quot;">​</a></h3><p>IFEval 高、IFBench 低：模型会做见过的格式体操，遇到新谓词就当建议。两张都高：更像真有一层「读取约束并监控输出表面」的能力。两张都低：服从通道本身弱，先别讨论泛化。只报 IFEval，会把过拟合写成对齐成功。只报 IFBench、不报 IFEval，则无法与已有文献对表——校准端仍然需要。</p><p><span class="marginnote">把 IFEval 的 verifier 直接当 RL 奖励时，应预先把 IFBench 锁进评测、不进奖励。否则留出集很快也会被「间接」优化，只是梯度来自相近约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IFEval 的实例是自然语言指令加若干原子约束 \\(C_i\\)。对输出 \\(o\\)：</p> \\[\\mathrm{PromptAcc}=\\frac{1}{N}\\sum_i\\mathbf{1}\\bigl[\\forall c\\in C_i:c(o)\\bigr],\\quad \\mathrm{InstAcc}=\\frac{\\sum_{i,c}\\mathbf{1}[c(o)]}{\\sum_i|C_i|}. \\]<p>复现必须调用官方检查器：词的定义、换行、代码块内是否计数，都是标准的一部分。约束族要分列，见 <a href="/llm/ifeval">IFEval</a>。<span class="marginnote">数字实例：一条提示带 5 条约束，模型满足 4 条——instruction-level 记 \\(4/5=0.8\\)，prompt-level 记 0（漏一条即整题失败）。这就是「prompt-level 更接近用户」的含义：真实解析器不给你部分分，JSON 少一个逗号就解析失败。</span></p><p>IFBench 沿用「谓词打分」骨架，替换约束库存与抽样：新的原子类型（IFEval 未覆盖的格式、条件更绕的计数、更易与助手默认文风冲突的禁令），以及更狠的组合。读分时同样应给 prompt-level 与 instruction-level，并按<strong>是否与 IFEval 约束族重叠</strong>切片。重叠切片用于校准（两套检查器是否同方向）；非重叠切片才是泛化命题。</p><p>解码协议两边必须一致：温度、<code>max_new_tokens</code>、系统提示、是否 <a href="/llm/constrained-decoding">约束解码</a>。JSON mode 会把某一族变成语法保证，应分列「纯采样 / 带文法」两表，且 IFBench 里文法覆盖不到的软约束（语气词、段落修辞）仍归模型。</p><h3 id="多轮修订是另一轴-不要混进单轮分" tabindex="-1">多轮修订是另一轴，不要混进单轮分 <a class="header-anchor" href="#多轮修订是另一轴-不要混进单轮分" aria-label="Permalink to &quot;多轮修订是另一轴，不要混进单轮分&quot;">​</a></h3><p>用户说「再短一点、但保留第二条禁词」，是指令遵循的时间维：要在已生成内容上打补丁，而不是从空缓冲满足静态谓词。IFEval 主协议是单轮。IFBench 一类后续集若含多轮，必须单独成表——单轮高、多轮低，说明模型会「一次写对格式」，不会「按反馈改格式」。把多轮平均进单轮，会让失败不可归因。</p>',17)),(n(),i(s,null,{default:E(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20GEN%5B%22%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%22%5D%0A%20%20GEN%20--%3E%20V1%5B%22IFEval%20%E5%AE%98%E6%96%B9%E8%B0%93%E8%AF%8D%22%5D%0A%20%20GEN%20--%3E%20V2%5B%22IFBench%20%E7%95%99%E5%87%BA%E8%B0%93%E8%AF%8D%22%5D%0A%20%20V1%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%3A%20%E8%A7%81%E8%BF%87%E7%9A%84%E7%BA%A6%E6%9D%9F%E6%97%8F%22%5D%0A%20%20V2%20--%3E%20OOD%5B%22%E6%B3%9B%E5%8C%96%3A%20%E6%96%B0%E7%BA%A6%E6%9D%9F%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20RL%5B%22%E7%94%A8%20IFEval%20%E5%BD%93%E5%A5%96%E5%8A%B1%22%5D%20--%3E%7C%22%E8%BF%87%E6%8B%9F%E5%90%88%E9%A3%8E%E9%99%A9%22%7C%20CAL%0A%20%20RL%20-.-%3E%7C%22%E5%BA%94%E9%9A%94%E7%A6%BB%22%7C%20OOD%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("可验证服从要求生成过程里有一个对表面形式的监控：段数、禁用词、括号是否闭合。这可以是隐式状态，也可以是把约束复述进思维。IFEval 的原子大多局部、可在短答案上满足；对齐若奖励「详尽」，会与长度上限系统性打架，长度族先掉。IFBench 的新约束若故意与默认助手文风冲突（更怪的格式、更窄的字符集），掉分反映的是"),l("strong",null,"默认策略与约束的 KL 距离"),e("，不只是「没看见指令」。")],-1)),a[5]||(a[5]=l("p",null,"过拟合检查器的机制很具体：重复空行凑段、用 unicode 同形字绕过英文禁用词、把 JSON 包在符合「必须出现」的套话里。校准端 verifier 越固定，这些策略越稳。留出端若换了计数单位或换了「何谓一段」的定义，作弊策略会失效——这正是留出的诊断价值。反之，若留出谓词实现得与 IFEval 过于同构（只是换了关键词表），过拟合仍会转移。",-1)),(n(),i(s,null,{default:E(()=>[o(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%AF%B9%E5%9B%BA%E5%AE%9A%E8%B0%93%E8%AF%8D%E7%9A%84%E4%BD%9C%E5%BC%8A%E7%AD%96%E7%95%A5%22%5D%20--%3E%20H1%5B%22%E9%87%8D%E5%A4%8D%E7%A9%BA%E8%A1%8C%E5%87%91%E6%AE%B5%E6%95%B0%22%5D%0A%20%20G%20--%3E%20H2%5B%22unicode%20%E5%90%8C%E5%BD%A2%E5%AD%97%E7%BB%95%E7%A6%81%E8%AF%8D%22%5D%0A%20%20G%20--%3E%20H3%5B%22JSON%20%E5%A1%9E%E8%BF%9B%E6%8C%87%E5%AE%9A%E5%A5%97%E8%AF%9D%22%5D%0A%20%20H1%20--%3E%20P%5B%22IFEval%20%E9%AB%98%E5%88%86%22%5D%0A%20%20H2%20--%3E%20P%0A%20%20H3%20--%3E%20P%0A%20%20P%20--%3E%20HO%5B%22IFBench%20%E6%8D%A2%E8%AE%A1%E6%95%B0%E5%8D%95%E4%BD%8D%20%2F%20%E6%AE%B5%E8%90%BD%E5%AE%9A%E4%B9%89%22%5D%0A%20%20HO%20--%3E%20F%5B%22%E4%BD%9C%E5%BC%8A%E5%A4%B1%E6%95%88%20%E7%9C%9F%E5%AE%9E%E6%9C%8D%E4%BB%8E%E8%A2%AB%E6%9A%B4%E9%9C%B2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<h3 id="必须出现易、禁止与计数难-在留出集上仍然成立" tabindex="-1">必须出现易、禁止与计数难，在留出集上仍然成立 <a class="header-anchor" href="#必须出现易、禁止与计数难-在留出集上仍然成立" aria-label="Permalink to &quot;必须出现易、禁止与计数难，在留出集上仍然成立&quot;">​</a></h3><p>关键词插入是服从；禁止是与语言模型先验作对；计数是对已写 token 的离散状态。IFBench 若在禁止与计数上掉得比「必须包含」更多，与 IFEval 的机制叙事一致，说明不是题出歪了。若反过来只有新「必须包含」在掉，更像是模型没把新词读进约束列表——提示解析问题，不是监控问题。分族报告才能读这一层。<span class="marginnote">常见误区：初学者容易以为「数够 3 个要点」和「包含关键词 A」难度差不多——实际上计数要求模型在逐 token 生成时维护一个离散计数器，而 Transformer 没有现成的寄存器做这件事；插关键词只需把词写进流即可。所以计数族在任何服从评测上都是重灾区。</span></p><p><span class="marginnote">中文产品不能只跑英文 IFEval / IFBench。字、词、标点、公文标题的谓词都要重写。英文高分不签发中文格式服从。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两套都不覆盖模糊风格（「幽默一点」）、冲突指令的优先级、工具是否调对、内容是否属实。高分无用、低分但内容极好，产品取舍仍要 Arena 或人工。可验证层适合 CI 与 RL 的可重复奖励，不适合当唯一质量分数。</p><p>检查器实现即标准。私自「收紧」或「放宽」谓词之后，与论文数字对比没有意义。IFBench 作为留出集，更要防训练泄漏：一旦检查器进入公开强化学习配方，它就变成新的 IFEval，需要再留出第三张卷。动态轮换的逻辑见 <a href="/llm/live-benchmarks">动态基准</a>。</p><p>与文法解码的边界：能被 schema 保证的，应从「模型服从」里划走，算系统能力。剩余软约束才是这两张表要盯的对象。混报会让开 JSON mode 的栈看起来「指令遵循强很多」。</p><p><span class="marginnote">prompt-level 比 instruction-level 更接近用户：漏一条就算失败。刷榜只报后者，会掩盖「经常漏一条」的模型。两套基准都应把两个数字写全。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IFEval 用固定可验证谓词测表面约束服从；IFBench 用留出约束类型测这种服从有没有过拟合检查器。</li><li>应同时报 prompt-level 与 instruction-level，并按约束族、按是否与 IFEval 重叠切片。</li><li>用 IFEval 做 RL 奖励时，必须把 IFBench 隔离在评测侧。</li><li>系统提示、截断、约束解码与中文谓词都会改分，须写入协议。</li><li>可验证高分不保证有用或属实；多轮修订应分表。</li><li>出处：Zhou et al., <em>Instruction-Following Evaluation for Large Language Models</em>；Pyatkin et al., IFBench / 可验证指令遵循的留出评测。</li></ul>',10))])}const D=A(c,[["render",p]]);export{u as __pageData,D as default};
